param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
$owners=@([Text.EncoderFallback],[Text.DecoderFallback],[Text.EncoderReplacementFallback],[Text.DecoderReplacementFallback],[Text.EncoderExceptionFallback],[Text.DecoderExceptionFallback],[Text.EncoderFallbackBuffer],[Text.DecoderFallbackBuffer]);$flags=[Reflection.BindingFlags]'Public,Instance,Static,DeclaredOnly';$metadata=@();$lookups=@()
foreach($owner in $owners){foreach($type in @($owner,$owner.MakeArrayType())){$metadata+=[ordered]@{fullName=$type.FullName;name=$type.Name;namespace=$type.Namespace;assemblyQualifiedName=$type.AssemblyQualifiedName;baseType=$type.BaseType.FullName;isAbstract=$type.IsAbstract;isSealed=$type.IsSealed;isPublic=$type.IsPublic;isClass=$type.IsClass;isValueType=$type.IsValueType;isSerializable=$type.IsSerializable;interfaces=@($type.GetInterfaces()|ForEach-Object FullName)}
 foreach($query in @($type.FullName,$type.FullName.ToLowerInvariant(),$type.AssemblyQualifiedName,($type.FullName+', mscorlib'))){foreach($ignoreCase in @($false,$true)){$resolved=[Type]::GetType($query,$false,$ignoreCase);$lookups+=[ordered]@{query=$query;ignoreCase=$ignoreCase;resolved=$(if($null -eq $resolved){$null}else{$resolved.FullName})}}}
}}
$declarations=@(foreach($owner in $owners){[ordered]@{fullName=$owner.FullName;constructors=@($owner.GetConstructors($flags)|ForEach-Object ToString);methods=@(foreach($method in $owner.GetMethods($flags)){[ordered]@{name=$method.Name;returnType=$method.ReturnType.ToString();isStatic=$method.IsStatic;parameters=@($method.GetParameters()|ForEach-Object {$_.ParameterType.ToString()});signature=$method.ToString()}})}})
$targets=@([object])+$owners;$relations=@();foreach($target in $targets){foreach($source in $targets){$relations+=[ordered]@{target=$target.FullName;source=$source.FullName;assignable=$target.IsAssignableFrom($source);subclass=$source.IsSubclassOf($target)}}}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();types=$metadata;lookups=$lookups;declarations=$declarations;relations=$relations;qualification='SELECTED_FALLBACK_TYPE_METADATA_AND_DECLARATION_INVENTORY_ONLY; MISSING_MEMBERS_FULL_REFLECTION_SOURCE_ABI_AND_TASK_ACCEPTANCE_OPEN'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 12)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS pinned fallback types: $($metadata.Count) shapes, $($lookups.Count) lookups, eight declaration inventories and $($relations.Count) relations"
